-- ----------------------------
-- Table structure for la_account_log
-- ----------------------------
DROP TABLE IF EXISTS `la_account_log`;
CREATE TABLE `la_account_log`  (
  `id` bigint(20) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '流水ID',
  `sn` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '流水单号',
  `admin_id` int(11) NULL DEFAULT NULL COMMENT '代理ID',
  `user_id` int(11) UNSIGNED NOT NULL DEFAULT 0 COMMENT '用户ID',
  `change_type` tinyint(2) UNSIGNED NOT NULL DEFAULT 0 COMMENT '变动类型: 1=充值, 2=提现, 3=投注, 4=中奖, 5=退款, 6=佣金, 7=调整, 8=冻结, 9=解冻',
  `change_amount` decimal(15, 2) NOT NULL DEFAULT 0.00 COMMENT '变动金额',
  `balance_before` decimal(15, 2) NOT NULL DEFAULT 0.00 COMMENT '变动前余额',
  `balance_after` decimal(15, 2) NOT NULL DEFAULT 0.00 COMMENT '变动后余额',
  `frozen_before` decimal(15, 2) NULL DEFAULT 0.00 COMMENT '变动前冻结',
  `frozen_after` decimal(15, 2) NULL DEFAULT 0.00 COMMENT '变动后冻结',
  `related_sn` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '关联单号',
  `related_type` tinyint(2) UNSIGNED NULL DEFAULT 0 COMMENT '关联类型: 1=投注, 2=充值, 3=提现, 4=佣金',
  `remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '备注',
  `operator_id` int(11) UNSIGNED NULL DEFAULT 0 COMMENT '操作人ID',
  `ip` varchar(39) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '操作IP',
  `created_at` int(10) UNSIGNED NOT NULL COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_sn`(`sn`) USING BTREE,
  INDEX `idx_user_created`(`user_id`, `created_at`) USING BTREE,
  INDEX `idx_change_type`(`change_type`) USING BTREE,
  INDEX `idx_related_sn`(`related_sn`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 48 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '账户流水表' ROW_FORMAT = Dynamic;

