-- ----------------------------
-- Table structure for la_article_collect
-- ----------------------------
DROP TABLE IF EXISTS `la_article_collect`;
CREATE TABLE `la_article_collect`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键',
  `user_id` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '用户ID',
  `article_id` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '文章ID',
  `status` tinyint(1) UNSIGNED NOT NULL DEFAULT 0 COMMENT '收藏状态 0-未收藏 1-已收藏',
  `create_time` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '创建时间',
  `update_time` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '更新时间',
  `delete_time` int(10) NULL DEFAULT NULL COMMENT '删除时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '文章收藏表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of la_article_collect
-- ----------------------------

-- ----------------------------
-- Table structure for la_best_plan
-- ----------------------------
DROP TABLE IF EXISTS `la_best_plan`;
CREATE TABLE `la_best_plan`  (
  `id` bigint(20) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '计划ID',
  `game_id` int(11) UNSIGNED NOT NULL DEFAULT 0 COMMENT '游戏ID',
  `issue_id` bigint(20) UNSIGNED NOT NULL DEFAULT 0 COMMENT '期次ID',
  `issue` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '期号',
  `analysis_time` int(10) UNSIGNED NOT NULL COMMENT '分析时间',
  `best_result` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '最佳开奖结果 (利润最大)',
  `best_profit` decimal(15, 2) NULL DEFAULT 0.00 COMMENT '最佳利润',
  `worst_result` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '最差开奖结果 (损失最大)',
  `worst_profit` decimal(15, 2) NULL DEFAULT 0.00 COMMENT '最差利润 (负数)',
  `profit_rate` decimal(5, 2) NULL DEFAULT 0.00 COMMENT '利润率 (%)',
  `risk_level` tinyint(1) UNSIGNED NULL DEFAULT 0 COMMENT '风险等级: 0=低风险, 1=中风险, 2=高风险',
  `detail_data` json NULL COMMENT '详细数据 JSON (包含各号码利润分析)',
  `recommendation` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '控盘建议',
  `created_at` int(10) UNSIGNED NOT NULL COMMENT '创建时间',
  `updated_at` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_issue`(`issue_id`) USING BTREE,
  INDEX `idx_game_issue`(`game_id`, `issue`) USING BTREE,
  INDEX `idx_analysis_time`(`analysis_time`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '最佳控盘计划表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of la_best_plan
-- ----------------------------

-- ----------------------------
-- Table structure for la_best_plan_history
-- ----------------------------
DROP TABLE IF EXISTS `la_best_plan_history`;
CREATE TABLE `la_best_plan_history`  (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `gid` int(11) NOT NULL COMMENT '游戏ID（100=香港六合彩，200=新澳门，300=澳门六合彩）',
  `qishu` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '期号（如 2025001）',
  `plate_code` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'A' COMMENT '盘口代码（A/B/C）',
  `analyze_time` datetime NOT NULL COMMENT '分析时间',
  `total_bets` decimal(15, 2) NOT NULL DEFAULT 0.00 COMMENT '总投注额',
  `total_orders` int(11) NOT NULL DEFAULT 0 COMMENT '总投注笔数',
  `best_numbers` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '最佳7个号码（逗号分隔，如\"1,2,3,4,5,6,7\"）',
  `best_profit` decimal(15, 2) NOT NULL COMMENT '最高利润额',
  `best_profit_rate` decimal(5, 2) NOT NULL COMMENT '最高利润率（%）',
  `worst_number` tinyint(2) NOT NULL DEFAULT 0 COMMENT '亏损最大号码（预留）',
  `worst_profit` decimal(15, 2) NOT NULL DEFAULT 0.00 COMMENT '最大亏损额（预留）',
  `worst_profit_rate` decimal(5, 2) NOT NULL DEFAULT 0.00 COMMENT '最大亏损率（预留）',
  `avg_profit` decimal(15, 2) NOT NULL COMMENT '平均利润',
  `number_details` json NOT NULL COMMENT '49个号码的详细盈亏数据（JSON数组）',
  `status` tinyint(1) NOT NULL DEFAULT 0 COMMENT '状态（0=未开奖，1=已开奖，2=已验证）',
  `actual_number` tinyint(2) NULL DEFAULT NULL COMMENT '实际开出号码',
  `actual_profit` decimal(15, 2) NULL DEFAULT NULL COMMENT '实际利润',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_gid_qishu_plate`(`gid`, `qishu`, `plate_code`) USING BTREE,
  INDEX `idx_analyze_time`(`analyze_time`) USING BTREE,
  INDEX `idx_status`(`status`) USING BTREE,
  INDEX `idx_plate_code`(`plate_code`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 3 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '最佳控盘分析历史记录（新表）' ROW_FORMAT = Dynamic;

