INSERT INTO `la_best_plan_history` VALUES (2, 200, '2025121102', 'A', '2025-12-12 01:52:06', 160.00, 16, '1,2,3,4,5,6,7', 160.00, 100.00, 0, 0.00, 0.00, 0.00, '[{\"number\": 1, \"profit\": 22.857142857142858, \"bet_count\": 0, \"risk_level\": 0, \"profit_rate\": 100, \"prize_amount\": 0}, {\"number\": 2, \"profit\": 22.857142857142858, \"bet_count\": 0, \"risk_level\": 0, \"profit_rate\": 100, \"prize_amount\": 0}, {\"number\": 3, \"profit\": 22.857142857142858, \"bet_count\": 0, \"risk_level\": 0, \"profit_rate\": 100, \"prize_amount\": 0}, {\"number\": 4, \"profit\": 22.857142857142858, \"bet_count\": 0, \"risk_level\": 0, \"profit_rate\": 100, \"prize_amount\": 0}, {\"number\": 5, \"profit\": 22.857142857142858, \"bet_count\": 0, \"risk_level\": 0, \"profit_rate\": 100, \"prize_amount\": 0}, {\"number\": 6, \"profit\": 22.857142857142858, \"bet_count\": 0, \"risk_level\": 0, \"profit_rate\": 100, \"prize_amount\": 0}, {\"number\": 7, \"profit\": 22.857142857142858, \"bet_count\": 0, \"risk_level\": 0, \"profit_rate\": 100, \"prize_amount\": 0}]', 0, NULL, NULL);

-- ----------------------------
-- Table structure for la_betting_record
-- ----------------------------
DROP TABLE IF EXISTS `la_betting_record`;
CREATE TABLE `la_betting_record`  (
  `id` bigint(20) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '投注ID',
  `sn` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '投注单号',
  `user_id` int(11) UNSIGNED NOT NULL DEFAULT 0 COMMENT '用户ID',
  `game_id` int(11) UNSIGNED NOT NULL DEFAULT 0 COMMENT '游戏ID',
  `plate_id` int(11) UNSIGNED NOT NULL DEFAULT 0 COMMENT '盘口ID',
  `plate_code` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '盘口代码',
  `issue_id` bigint(20) UNSIGNED NOT NULL DEFAULT 0 COMMENT '期次ID',
  `issue` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '期号',
  `method_id` int(11) UNSIGNED NOT NULL DEFAULT 0 COMMENT '玩法ID',
  `method_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '玩法名称',
  `bet_content` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '投注内容',
  `bet_amount` decimal(15, 2) NOT NULL DEFAULT 0.00 COMMENT '单注金额',
  `bet_multiple` int(11) UNSIGNED NULL DEFAULT 1 COMMENT '投注倍数',
  `total_amount` decimal(15, 2) NOT NULL DEFAULT 0.00 COMMENT '总金额',
  `odds` decimal(10, 2) NULL DEFAULT 0.00 COMMENT '赔率',
  `status` tinyint(2) UNSIGNED NULL DEFAULT 0 COMMENT '状态: 0=待开奖, 1=已中奖, 2=未中奖, 3=已撤单',
  `prize_amount` decimal(15, 2) NULL DEFAULT 0.00 COMMENT '中奖金额',
  `is_settled` tinyint(1) UNSIGNED NULL DEFAULT 0 COMMENT '是否已结算',
  `settled_at` int(10) UNSIGNED NULL DEFAULT 0 COMMENT '结算时间',
  `parent_id` int(11) UNSIGNED NULL DEFAULT 0 COMMENT '上级ID',
  `ancestor_ids` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '祖先ID链',
  `ip` varchar(39) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT 'IP地址',
  `created_at` int(10) UNSIGNED NOT NULL COMMENT '创建时间',
  `updated_at` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_sn`(`sn`) USING BTREE,
  INDEX `idx_user_created`(`user_id`, `created_at`) USING BTREE,
  INDEX `idx_issue_status`(`issue_id`, `status`) USING BTREE,
  INDEX `idx_plate_issue`(`plate_id`, `issue`) USING BTREE,
  INDEX `idx_status`(`status`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 42 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '投注记录表(支持多盘)' ROW_FORMAT = Dynamic;

