-- ----------------------------
-- Table structure for la_game
-- ----------------------------
DROP TABLE IF EXISTS `la_game`;
CREATE TABLE `la_game`  (
  `id` int(11) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '游戏ID',
  `category_id` int(11) UNSIGNED NOT NULL DEFAULT 0 COMMENT '游戏分类ID (关联 la_game_category)',
  `code` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '游戏编码 (如: hk_lhc, cq_ssc)',
  `name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '游戏名称 (如: 香港六合彩, 重庆时时彩)',
  `short_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '游戏简称 (如: 港彩, 重庆)',
  `icon` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '游戏图标URL',
  `description` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '游戏描述',
  `draw_count` tinyint(4) UNSIGNED NULL DEFAULT 1 COMMENT '开奖号码数量 (如: 六合彩=7, 时时彩=5)',
  `draw_rule` json NULL COMMENT '开奖规则配置 JSON {number_range: [1, 49], special: true}',
  `time_config` json NULL COMMENT '时间配置 JSON {open_time: \"06:00:00\", close_time: \"09:30:00\", draw_time: \"09:50:00\", draw_interval: 1440}',
  `bet_config` json NULL COMMENT '投注配置 JSON {min_bet: 1, max_bet: 10000, max_prize: 1000000}',
  `is_official` tinyint(1) UNSIGNED NULL DEFAULT 0 COMMENT '是否官方游戏: 0=非官方, 1=官方',
  `is_fast_lottery` tinyint(1) UNSIGNED NULL DEFAULT 0 COMMENT '是否快开彩: 0=普通, 1=快开彩',
  `status` tinyint(1) UNSIGNED NULL DEFAULT 1 COMMENT '游戏状态: 0=维护中, 1=正常, 2=已下线',
  `sort` int(11) NULL DEFAULT 0 COMMENT '排序值',
  `created_at` int(10) UNSIGNED NOT NULL COMMENT '创建时间',
  `updated_at` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '更新时间',
  `deleted_at` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '删除时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_code`(`code`) USING BTREE,
  INDEX `idx_category`(`category_id`) USING BTREE,
  INDEX `idx_status_sort`(`status`, `sort`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 301 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '游戏表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of la_game
