-- ----------------------------
-- Table structure for la_game_category
-- ----------------------------
DROP TABLE IF EXISTS `la_game_category`;
CREATE TABLE `la_game_category`  (
  `id` int(11) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '分类ID',
  `code` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '分类编码 (如: lhc, ssc, k3)',
  `name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '分类名称 (如: 六合彩, 时时彩)',
  `icon` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '分类图标URL',
  `description` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '分类描述',
  `sort` int(11) NULL DEFAULT 0 COMMENT '排序值 (数字越小越靠前)',
  `is_enabled` tinyint(1) UNSIGNED NULL DEFAULT 1 COMMENT '是否启用: 0=禁用, 1=启用',
  `created_at` int(10) UNSIGNED NOT NULL COMMENT '创建时间 (Unix时间戳)',
  `updated_at` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '更新时间 (Unix时间戳)',
  `deleted_at` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '删除时间 (Unix时间戳, 软删除)',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_code`(`code`) USING BTREE COMMENT '编码唯一索引',
  INDEX `idx_enabled_sort`(`is_enabled`, `sort`) USING BTREE COMMENT '启用状态+排序复合索引'
) ENGINE = InnoDB AUTO_INCREMENT = 4 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '游戏分类表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of la_game_category
-- ----------------------------
