INSERT INTO `la_operation_log` VALUES (7, 1, 'admin', 'admin', ' 获取管理员信息接口', 'GET', 'http://localhost/adminapi/lottery_login/getAdminInfo', '[]', '<!DOCTYPE html>\n<html>\n<head>\n    <meta charset=\"UTF-8\">\n    <title>系统发生错误</title>\n    <meta name=\"robots\" content=\"noindex,nofollow\" />\n    <style>\n        /* Base */\n        body {\n            color: #333;\n            font: 16px Verdana, \"Helvetica Neue\", helvetica, Arial, \'Microsoft YaHei\', sans-serif;\n            margin: 0;\n            padding: 0 20px 20px;\n        }\n        h1{\n            margin: 10px 0 0;\n            font-size: 28px;\n            font-weight: 500;\n            line-height: 32px;\n        }\n        h2{\n            color: #4288ce;\n            font-weight: 400;\n            padding: 6px 0;\n            margin: 6px 0 0;\n            font-size: 18px;\n            border-bottom: 1px solid #eee;\n        }\n        h3{\n            margin: 12px;\n            font-size: 16px;\n            font-weight: bold;\n        }\n        abbr{\n            cursor: help;\n            text-decoration: underline;\n            text-decoration-style: dotted;\n        }\n        a{\n            color: #868686;\n            cursor: pointer;\n        }\n        a:hover{\n            text-decoration: underline;\n        }\n        .line-error{\n            background: #f8cbcb;\n        }\n        .echo table {\n            width: 100%;\n        }\n        .echo pre {\n            padding: 16px;\n            overflow: auto;\n            font-size: 85%;\n            line-height: 1.45;\n            background-color: #f7f7f7;\n            border: 0;\n            border-radius: 3px;\n            font-family: Consolas, \"Liberation Mono\", Menlo, Courier, monospace;\n        }\n        .echo pre > pre {\n            padding: 0;\n            margin: 0;\n        }\n        /* Exception Info */\n        .exception {\n            margin-top: 20px;\n        }\n        .exception .message{\n            padding: 12px;\n            border: 1px solid #ddd;\n            border-bottom: 0 none;\n            line-height: 18px;\n            font-size:16px;\n            border-top-left-radius: 4px;\n            border-top-right-radius: 4px;\n            font-family: Consolas,\"Liberation Mono\",Courier,Verdana,\"微软雅黑\",serif;\n        }\n        .exception .code{\n            float: left;\n            text-align: center;\n            color: #fff;\n            margin-right: 12px;\n            padding: 16px;\n            border-radius: 4px;\n            background: #999;\n        }\n        .exception .source-code{\n            padding: 6px;\n            border: 1px solid #ddd;\n\n            background: #f9f9f9;\n            overflow-x: auto;\n\n        }\n        .exception .source-code pre{\n            margin: 0;\n        }\n        .exception .source-code pre ol{\n            margin: 0;\n            color: #4288ce;\n            display: inline-block;\n            min-width: 100%;\n            box-sizing: border-box;\n            font-size:14px;\n            font-family: \"Century Gothic\",Consolas,\"Liberation Mono\",Courier,Verdana,serif;\n            padding-left: 40px;\n        }\n        .exception .source-code pre li{\n            border-left: 1px solid #ddd;\n            height: 18px;\n            line-height: 18px;\n        }\n        .exception .source-code pre code{\n            color: #333;\n            height: 100%;\n            display: inline-block;\n            border-left: 1px solid #fff;\n            font-size:14px;\n            font-family: Consolas,\"Liberation Mono\",Courier,Verdana,\"微软雅黑\",serif;\n        }\n        .exception .trace{\n            padding: 6px;\n            border: 1px solid #ddd;\n            border-top: 0 none;\n            line-height: 16px;\n            font-size:14px;\n            font-family: Consolas,\"Liberation Mono\",Courier,Verdana,\"微软雅黑\",serif;\n        }\n        .exception .trace h2:hover {\n            text-decoration: un