-- ----------------------------
-- Table structure for la_plate
-- ----------------------------
DROP TABLE IF EXISTS `la_plate`;
CREATE TABLE `la_plate`  (
  `id` int(11) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '盘口ID',
  `code` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '盘口代码(如A、B、C)',
  `name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '盘口名称',
  `game_id` int(11) NOT NULL DEFAULT 200 COMMENT '游戏ID',
  `open_time` varchar(5) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '06:00' COMMENT '开盘时间(HH:mm格式)',
  `close_time` varchar(5) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '09:30' COMMENT '封盘时间(HH:mm格式)',
  `draw_time` varchar(5) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '09:50' COMMENT '开奖时间(HH:mm格式)',
  `close_advance` int(11) NOT NULL DEFAULT 5 COMMENT '提前封盘分钟数',
  `status` tinyint(1) NOT NULL DEFAULT 1 COMMENT '状态(0=禁用, 1=启用)',
  `sort` int(11) NOT NULL DEFAULT 0 COMMENT '排序(数字越小越靠前)',
  `remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `created_at` int(11) NOT NULL DEFAULT 0 COMMENT '创建时间',
  `updated_at` int(11) NOT NULL DEFAULT 0 COMMENT '更新时间',
  `deleted_at` int(11) NULL DEFAULT NULL COMMENT '删除时间(软删除)',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_code`(`code`, `deleted_at`) USING BTREE,
  INDEX `idx_game_id`(`game_id`) USING BTREE,
  INDEX `idx_status`(`status`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 5 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '盘口配置表' ROW_FORMAT = Dynamic;

