-- ----------------------------
-- Table structure for la_play_category
-- ----------------------------
DROP TABLE IF EXISTS `la_play_category`;
CREATE TABLE `la_play_category`  (
  `id` int(11) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '分类ID',
  `game_id` int(11) UNSIGNED NOT NULL DEFAULT 0 COMMENT '游戏ID (关联 la_game)',
  `code` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '分类编码 (如: tema, zhengma, shengxiao)',
  `name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '分类名称 (如: 特码, 正码, 生肖)',
  `description` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '分类描述',
  `icon` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '分类图标',
  `sort` int(11) NULL DEFAULT 0 COMMENT '排序值',
  `is_enabled` tinyint(1) UNSIGNED NULL DEFAULT 1 COMMENT '是否启用: 0=禁用, 1=启用',
  `created_at` int(10) UNSIGNED NOT NULL COMMENT '创建时间',
  `updated_at` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '更新时间',
  `deleted_at` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '删除时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_game_code`(`game_id`, `code`) USING BTREE,
  INDEX `idx_game_enabled_sort`(`game_id`, `is_enabled`, `sort`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 6 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '玩法大类表' ROW_FORMAT = Dynamic;

