-- ----------------------------
-- Table structure for la_play_method
-- ----------------------------
DROP TABLE IF EXISTS `la_play_method`;
CREATE TABLE `la_play_method`  (
  `id` int(11) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '玩法ID',
  `game_id` int(11) UNSIGNED NOT NULL DEFAULT 0 COMMENT '游戏ID',
  `name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '玩法名称',
  `code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '玩法代码',
  `odds_default` decimal(10, 2) NULL DEFAULT 0.00 COMMENT '默认赔率',
  `odds_min` decimal(10, 2) NULL DEFAULT 0.00 COMMENT '最小赔率',
  `odds_max` decimal(10, 2) NULL DEFAULT 0.00 COMMENT '最大赔率',
  `prize_config` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '中奖规则配置(JSON)',
  `is_enabled` tinyint(1) UNSIGNED NULL DEFAULT 1 COMMENT '是否启用',
  `sort` int(11) UNSIGNED NULL DEFAULT 0 COMMENT '排序',
  `created_at` int(10) UNSIGNED NOT NULL COMMENT '创建时间',
  `updated_at` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_game_enabled`(`game_id`, `is_enabled`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 10 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '玩法配置表' ROW_FORMAT = Dynamic;

