-- ----------------------------
-- Table structure for la_play_odds
-- ----------------------------
DROP TABLE IF EXISTS `la_play_odds`;
CREATE TABLE `la_play_odds`  (
  `id` int(11) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '赔率ID',
  `method_id` int(11) UNSIGNED NOT NULL DEFAULT 0 COMMENT '玩法方法ID (关联 la_play_method)',
  `user_id` int(11) UNSIGNED NULL DEFAULT 0 COMMENT '用户ID (0表示默认配置, 非0表示用户专属赔率)',
  `user_level` tinyint(4) UNSIGNED NULL DEFAULT 0 COMMENT '用户层级 (0=默认, 1=普通会员, 2=VIP, 3=代理)',
  `odds` decimal(10, 4) NOT NULL DEFAULT 0.0000 COMMENT '赔率',
  `rebate_rate` decimal(5, 2) NULL DEFAULT 0.00 COMMENT '返水比例 (%)',
  `is_enabled` tinyint(1) UNSIGNED NULL DEFAULT 1 COMMENT '是否启用',
  `created_at` int(10) UNSIGNED NOT NULL COMMENT '创建时间',
  `updated_at` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_method_user`(`method_id`, `user_id`) USING BTREE,
  INDEX `idx_user`(`user_id`) USING BTREE,
  INDEX `idx_method_level`(`method_id`, `user_level`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '玩法赔率配置表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of la_play_odds
-- ----------------------------

-- ----------------------------
-- Table structure for la_play_statistics
-- ----------------------------
DROP TABLE IF EXISTS `la_play_statistics`;
CREATE TABLE `la_play_statistics`  (
  `id` bigint(20) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '统计ID',
  `game_id` int(11) UNSIGNED NOT NULL DEFAULT 0 COMMENT '游戏ID',
  `issue_id` bigint(20) UNSIGNED NOT NULL DEFAULT 0 COMMENT '期次ID',
  `issue` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '期号',
  `method_id` int(11) UNSIGNED NOT NULL DEFAULT 0 COMMENT '玩法方法ID',
  `method_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '玩法名称',
  `total_bets` int(11) UNSIGNED NULL DEFAULT 0 COMMENT '投注笔数',
  `total_amount` decimal(15, 2) NULL DEFAULT 0.00 COMMENT '投注总金额',
  `potential_prize` decimal(15, 2) NULL DEFAULT 0.00 COMMENT '潜在派奖金额 (如果中奖)',
  `potential_profit` decimal(15, 2) NULL DEFAULT 0.00 COMMENT '潜在利润 (投注-潜在派奖)',
  `actual_prize` decimal(15, 2) NULL DEFAULT 0.00 COMMENT '实际派奖金额',
  `actual_profit` decimal(15, 2) NULL DEFAULT 0.00 COMMENT '实际利润',
  `created_at` int(10) UNSIGNED NOT NULL COMMENT '创建时间',
  `updated_at` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_issue_method`(`issue_id`, `method_id`) USING BTREE,
  INDEX `idx_game_issue`(`game_id`, `issue_id`) USING BTREE,
  INDEX `idx_method`(`method_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '玩法统计表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of la_play_statistics
-- ----------------------------

-- ----------------------------
-- Table structure for la_play_subcategory
-- ----------------------------
DROP TABLE IF EXISTS `la_play_subcategory`;
CREATE TABLE `la_play_subcategory`  (
  `id` int(11) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '子类ID',
  `category_id` int(11) UNSIGNED NOT NULL DEFAULT 0 COMMENT '玩法大类ID (关联 la_play_category)',
  `code` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '子类编码 (如: tema_dx, tema_ds, zhengma1)',
  `name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '子类名称 (如: 特码大小, 特码单双, 正码1)',
  `description` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '子类描述',
  `sort` int(11) NULL DEFAULT 0 COMMENT '排序值',
  `is_enabled` tinyint(1) UNSIGNED NULL DEFAULT 1 COMMENT '是否启用',
  `created_at` int(10) UNSIGNED NOT NULL COMMENT '创建时间',
  `updated_at` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '更新时间',
  `deleted_at` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '删除时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_category_code`(`category_id`, `code`) USING BTREE,
  INDEX `idx_category_enabled_sort`(`category_id`, `is_enabled`, `sort`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 7 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '玩法子类表' ROW_FORMAT = Dynamic;

