-- ----------------------------
-- Table structure for la_user_account
-- ----------------------------
DROP TABLE IF EXISTS `la_user_account`;
CREATE TABLE `la_user_account`  (
  `id` int(11) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '账户ID',
  `user_id` int(11) UNSIGNED NOT NULL DEFAULT 0 COMMENT '用户ID',
  `balance` decimal(15, 2) NOT NULL DEFAULT 0.00 COMMENT '账户余额',
  `frozen_amount` decimal(15, 2) NOT NULL DEFAULT 0.00 COMMENT '冻结金额',
  `total_recharge` decimal(15, 2) NULL DEFAULT 0.00 COMMENT '累计充值',
  `total_withdraw` decimal(15, 2) NULL DEFAULT 0.00 COMMENT '累计提现',
  `total_bet` decimal(15, 2) NULL DEFAULT 0.00 COMMENT '累计投注',
  `total_prize` decimal(15, 2) NULL DEFAULT 0.00 COMMENT '累计中奖',
  `total_commission` decimal(15, 2) NULL DEFAULT 0.00 COMMENT '累计佣金',
  `status` tinyint(1) UNSIGNED NULL DEFAULT 1 COMMENT '状态: 0=冻结, 1=正常',
  `version` int(11) UNSIGNED NULL DEFAULT 0 COMMENT '版本号(乐观锁)',
  `created_at` int(10) UNSIGNED NOT NULL COMMENT '创建时间',
  `updated_at` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_user`(`user_id`) USING BTREE,
  INDEX `idx_balance`(`balance`) USING BTREE,
  INDEX `idx_status`(`status`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 4 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '用户账户表' ROW_FORMAT = Dynamic;

