-- ----------------------------
-- Table structure for la_user_plate
-- ----------------------------
DROP TABLE IF EXISTS `la_user_plate`;
CREATE TABLE `la_user_plate`  (
  `id` int(11) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `user_id` int(11) NOT NULL COMMENT '用户ID(关联la_user表)',
  `plate_id` int(11) NOT NULL COMMENT '盘口ID(关联la_plate表)',
  `plate_code` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '盘口代码(冗余字段,便于查询)',
  `is_agent` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否代理(0=普通会员, 1=代理)',
  `agent_level` tinyint(2) NOT NULL DEFAULT 0 COMMENT '代理等级(0=普通会员, 1=一级代理, 2=二级代理)',
  `commission_rate` decimal(5, 2) NOT NULL DEFAULT 0.00 COMMENT '佣金比例(%)',
  `status` tinyint(1) NOT NULL DEFAULT 1 COMMENT '状态(0=禁用, 1=启用)',
  `created_at` int(11) NOT NULL DEFAULT 0 COMMENT '创建时间',
  `updated_at` int(11) NOT NULL DEFAULT 0 COMMENT '更新时间',
  `deleted_at` int(11) NULL DEFAULT NULL COMMENT '删除时间(软删除)',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_user_plate`(`user_id`, `plate_id`, `deleted_at`) USING BTREE,
  INDEX `idx_user_id`(`user_id`) USING BTREE,
  INDEX `idx_plate_id`(`plate_id`) USING BTREE,
  INDEX `idx_plate_code`(`plate_code`) USING BTREE,
  INDEX `idx_is_agent`(`is_agent`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '用户盘口关系表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of la_user_plate
-- ----------------------------

-- ----------------------------
-- Table structure for la_user_play_limit
-- ----------------------------
DROP TABLE IF EXISTS `la_user_play_limit`;
CREATE TABLE `la_user_play_limit`  (
  `id` int(11) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '限额ID',
  `user_id` int(11) UNSIGNED NOT NULL DEFAULT 0 COMMENT '用户ID (0表示默认限额)',
  `game_id` int(11) UNSIGNED NOT NULL DEFAULT 0 COMMENT '游戏ID (0表示所有游戏)',
  `method_id` int(11) UNSIGNED NOT NULL DEFAULT 0 COMMENT '玩法方法ID (0表示所有玩法)',
  `min_bet` decimal(10, 2) NULL DEFAULT 1.00 COMMENT '单注最低金额',
  `max_bet` decimal(10, 2) NULL DEFAULT 10000.00 COMMENT '单注最高金额',
  `max_prize` decimal(15, 2) NULL DEFAULT 1000000.00 COMMENT '单期最高派奖金额',
  `daily_limit` decimal(15, 2) NULL DEFAULT 0.00 COMMENT '每日投注限额 (0=不限)',
  `is_enabled` tinyint(1) UNSIGNED NULL DEFAULT 1 COMMENT '是否启用',
  `created_at` int(10) UNSIGNED NOT NULL COMMENT '创建时间',
  `updated_at` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_user_game_method`(`user_id`, `game_id`, `method_id`) USING BTREE,
  INDEX `idx_user`(`user_id`) USING BTREE,
  INDEX `idx_game`(`game_id`) USING BTREE,
  INDEX `idx_method`(`method_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '用户玩法限额表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of la_user_play_limit
-- ----------------------------

-- ----------------------------
-- Table structure for la_user_session
-- ----------------------------
DROP TABLE IF EXISTS `la_user_session`;
CREATE TABLE `la_user_session`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `user_id` int(11) NOT NULL COMMENT '用户id',
  `terminal` tinyint(1) NOT NULL DEFAULT 1 COMMENT '客户端类型：1-微信小程序；2-微信公众号；3-手机H5；4-电脑PC；5-苹果APP；6-安卓APP',
  `token` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '令牌',
  `update_time` int(10) NULL DEFAULT NULL COMMENT '更新时间',
  `expire_time` int(10) NOT NULL COMMENT '到期时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `admin_id_client`(`user_id`, `terminal`) USING BTREE COMMENT '一个用户在一个终端只有一个token',
  UNIQUE INDEX `token`(`token`) USING BTREE COMMENT 'token是唯一的'
) ENGINE = InnoDB AUTO_INCREMENT = 2 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '用户会话表' ROW_FORMAT = Dynamic;

