-- ----------------------------
-- Table structure for la_winning_record
-- ----------------------------
DROP TABLE IF EXISTS `la_winning_record`;
CREATE TABLE `la_winning_record`  (
  `id` bigint(20) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '中奖ID',
  `betting_id` bigint(20) UNSIGNED NOT NULL DEFAULT 0 COMMENT '投注ID',
  `sn` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '投注单号',
  `user_id` int(11) UNSIGNED NOT NULL DEFAULT 0 COMMENT '用户ID',
  `game_id` int(11) UNSIGNED NOT NULL DEFAULT 0 COMMENT '游戏ID',
  `plate_id` int(11) UNSIGNED NOT NULL DEFAULT 0 COMMENT '盘口ID',
  `plate_code` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '盘口代码',
  `issue_id` bigint(20) UNSIGNED NOT NULL DEFAULT 0 COMMENT '期次ID',
  `issue` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '期号',
  `method_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '玩法名称',
  `bet_amount` decimal(15, 2) NOT NULL DEFAULT 0.00 COMMENT '投注金额',
  `odds` decimal(10, 2) NULL DEFAULT 0.00 COMMENT '赔率',
  `prize_amount` decimal(15, 2) NOT NULL DEFAULT 0.00 COMMENT '中奖金额',
  `net_profit` decimal(15, 2) NULL DEFAULT 0.00 COMMENT '净盈利',
  `is_paid` tinyint(1) UNSIGNED NULL DEFAULT 0 COMMENT '是否已派奖',
  `paid_at` int(10) UNSIGNED NULL DEFAULT 0 COMMENT '派奖时间',
  `created_at` int(10) UNSIGNED NOT NULL COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_betting`(`betting_id`) USING BTREE,
  INDEX `idx_user_created`(`user_id`, `created_at`) USING BTREE,
  INDEX `idx_issue`(`issue_id`) USING BTREE,
  INDEX `idx_plate_issue`(`plate_id`, `issue`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '中奖记录表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of la_winning_record
-- ----------------------------

-- ----------------------------
-- Procedure structure for auto_create_lottery_issues
-- ----------------------------
DROP PROCEDURE IF EXISTS `auto_create_lottery_issues`;
delimiter ;;
CREATE PROCEDURE `auto_create_lottery_issues`()
BEGIN
    DECLARE v_game_id INT DEFAULT 200;
    DECLARE v_current_date DATE;
    DECLARE v_last_issue VARCHAR(32);
    DECLARE v_new_issue VARCHAR(32);
    DECLARE v_need_create INT DEFAULT 0;
    DECLARE v_base_draw_time DATETIME;

    
    SET v_current_date = CURDATE();

    
    SELECT COUNT(*) INTO v_need_create
    FROM la_lottery_issue
    WHERE game_id = v_game_id
      AND DATE(FROM_UNIXTIME(draw_time)) = v_current_date
      AND status IN (0, 1, 2);  

    
    IF v_need_create > 0 THEN
        SELECT CONCAT('✅ 今天已有未开奖期号,无需创建. 共 ', v_need_create, ' 个期号未开奖') AS result;
    ELSE
        
        SELECT issue INTO v_last_issue
        FROM la_lottery_issue
        WHERE game_id = v_game_id
        ORDER BY id DESC
        LIMIT 1;

        
        IF v_last_issue IS NULL THEN
            
            SET v_new_issue = CONCAT(YEAR(NOW()), '001');
        ELSE
            
            SET v_new_issue = LPAD(CAST(v_last_issue AS UNSIGNED) + 1, LENGTH(v_last_issue), '0');
        END IF;

        
        
        SET v_base_draw_time = CONCAT(v_current_date, ' 02:00:00');
        IF NOW() >= v_base_draw_time THEN
            SET v_base_draw_time = DATE_ADD(v_base_draw_time, INTERVAL 1 DAY);
        END IF;

        
        INSERT INTO la_lottery_issue (
            game_id,
            plate_id,
            plate_code,
            issue,
            status,
            open_time,
            close_time,
            draw_time,
            created_at,
            updated_at
        ) VALUES (
            v_game_id,
            1,
            'A',
            v_new_issue,
            1,  
            UNIX_TIMESTAMP(DATE_SUB(v_base_draw_time, INTERVAL 90 MINUTE)),  
            UNIX_TIMESTAMP(DATE_SUB(v_base_draw_time, INTERVAL 60 MINUTE)),  
            UNIX_TIMESTAMP(v_base_draw_time),                                 
            UNIX_TIMESTAMP(NOW()),
            UNIX_TIMESTAMP(NOW())
        );

        
        INSERT INTO la_lottery_issue (
            game_id,
            plate_id,
            plate_code,
            issue,
            status,
            open_time,
            close_time,
            draw_time,
            created_at,
            updated_at
        ) VALUES (
            v_game_id,
            2,
            'B',
            v_new_issue,
            1,  
            UNIX_TIMESTAMP(DATE_SUB(v_base_draw_time, INTERVAL 80 MINUTE)),  
            UNIX_TIMESTAMP(DATE_SUB(v_base_draw_time, INTERVAL 50 MINUTE)),  
            UNIX_TIMESTAMP(DATE_ADD(v_base_draw_time, INTERVAL 10 MINUTE)),  
            UNIX_TIMESTAMP(NOW()),
            UNIX_TIMESTAMP(NOW())
        );

        
        INSERT INTO la_lottery_issue (
            game_id,
            plate_id,
            plate_code,
            issue,
            status,
            open_time,
            close_time,
            draw_time,
            created_at,
            updated_at
        ) VALUES (
            v_game_id,
            3,
            'C',
            v_new_issue,
            1,  
            UNIX_TIMESTAMP(DATE_SUB(v_base_draw_time, INTERVAL 70 MINUTE)),  
            UNIX_TIMESTAMP(DATE_SUB(v_base_draw_time, INTERVAL 40 MINUTE)),  
            UNIX_TIMESTAMP(DATE_ADD(v_base_draw_time, INTERVAL 20 MINUTE)),  
            UNIX_TIMESTAMP(NOW()),
            UNIX_TIMESTAMP(NOW())
        );

        
        SELECT CONCAT('✅ 成功创建新期号: ', v_new_issue) AS result;

        
        SELECT
            id,
            plate_code AS '盘口',
            issue AS '期号',
            CASE status
                WHEN 0 THEN '未开始'
                WHEN 1 THEN '投注中'
                WHEN 2 THEN '已封盘'
                WHEN 3 THEN '已开奖'
                ELSE '未知'
            END AS '状态',
            FROM_UNIXTIME(open_time, '%Y-%m-%d %H:%i:%s') AS '开盘时间',
            FROM_UNIXTIME(close_time, '%Y-%m-%d %H:%i:%s') AS '封盘时间',
            FROM_UNIXTIME(draw_time, '%Y-%m-%d %H:%i:%s') AS '开奖时间'
        FROM la_lottery_issue
        WHERE game_id = v_game_id
          AND issue = v_new_issue
        ORDER BY plate_code;
    END IF;

END
;;
delimiter ;

SET FOREIGN_KEY_CHECKS = 1;
